#!/usr/bin/env bash
# Reality Control: all application sources are embedded below. Dependencies require Internet.
# GENERATED by scripts/build_installer.py. Do not edit the generated payload manually.
set -Eeuo pipefail
umask 077
EXTRACT_ONLY=''
ARGS=()
usage() {
  cat <<'HELP'
Reality Control — один файл установки на Ubuntu 22.04/24.04/26.04.
  sudo bash install-reality-control.sh
  sudo bash install-reality-control.sh --with-xray
  sudo bash install-reality-control.sh --ip PUBLIC_IPV4 --https-port 8443
  sudo bash install-reality-control.sh --local-only
  bash install-reality-control.sh --extract-only EMPTY_DIRECTORY

По умолчанию: автоматический IPv4, Docker при его отсутствии, панель + host-agent,
HTTPS на 8443 с доверенным IP-сертификатом, новый администратор со случайным паролем.
--with-xray       Установить ядро на чистом VPS; существующее ядро не заменяется.
--prepare-existing Разрешить подготовку старого Xray (backup/test/restart/rollback).
--sni DOMAIN      REALITY target новой установки (по умолчанию www.wikipedia.org).
--local-only      Только новая локальная панель через SSH, без публичного HTTPS.
--ip IPV4         Явный IPv4 вместо автоматического определения.
--extract-only    Только проверить и распаковать исходники, ничего не устанавливать.
Существующие данные/пароли/UUID/ключи не заменяются. Зависимости скачиваются из Интернета.
HELP
}
while (( $# )); do
  case "$1" in
    --help|-h) usage; exit 0;;
    --extract-only) EXTRACT_ONLY="${2:?Нужен пустой каталог}"; shift 2;;
    --ip|--https-port|--sni) ARGS+=("$1" "${2:?Нужно значение параметра}"); shift 2;;
    --local-only|--with-xray|--prepare-existing) ARGS+=("$1"); shift;;
    *) echo "Неизвестный параметр: $1" >&2; exit 2;;
  esac
done
if [[ -z "$EXTRACT_ONLY" ]]; then
  [[ $EUID -eq 0 ]] || { echo 'Запустите установщик через sudo bash' >&2; exit 1; }
  [[ -r /etc/os-release ]] || exit 1
  source /etc/os-release
  [[ ${ID:-} == ubuntu && ${VERSION_ID:-} =~ ^(22.04|24.04|26.04)$ ]] || { echo 'Нужна Ubuntu 22.04/24.04/26.04' >&2; exit 1; }
  [[ ! -e /.dockerenv && -d /run/systemd/system ]] || { echo 'Запускайте на Ubuntu-хосте с systemd, не в контейнере' >&2; exit 1; }
  export DEBIAN_FRONTEND=noninteractive
  apt-get update -qq
  apt-get install -y -qq python3 curl ca-certificates iproute2 >/dev/null
  PYTHON=/usr/bin/python3
else
  PYTHON="${REALITY_PYTHON:-python3}"
  command -v "$PYTHON" >/dev/null || PYTHON=python
  command -v "$PYTHON" >/dev/null || { echo 'Для распаковки нужен Python 3' >&2; exit 1; }
fi
SELF="$(readlink -f -- "${BASH_SOURCE[0]}")"
TEMP="$(mktemp -d)"
cleanup() { rm -rf -- "$TEMP"; }
trap cleanup EXIT
awk 'found && substr($0,1,1)=="#" { print substr($0,2) } /^__REALITY_CONTROL_PAYLOAD__$/ { found=1 }' "$SELF" | base64 --decode > "$TEMP/payload.tar.gz"
printf '%s  %s\n' '2c9ed958decc77975fad68e4424393ae04274538135476525d2e8bf1e3c70d29' "$TEMP/payload.tar.gz" | sha256sum --check --status || { echo 'Повреждён пакет установщика' >&2; exit 1; }
DESTINATION="${EXTRACT_ONLY:-$TEMP/source}"
"$PYTHON" - "$TEMP/payload.tar.gz" "$DESTINATION" <<'PY_EXTRACT_REALITY'
"""Standalone safe extractor embedded into the single-file shell installer."""
import hashlib
import json
import os
from pathlib import Path, PurePosixPath
import sys
import tarfile

MANIFEST = 'BUNDLE-MANIFEST.json'


def safe_name(value):
    path = PurePosixPath(value)
    if (not value or path.is_absolute() or '..' in path.parts or '\\' in value
            or ':' in value or str(path) != value):
        raise ValueError('Недопустимый путь в пакете')
    return path


def extract(archive, destination):
    destination = Path(destination)
    if destination.is_symlink() or (destination.exists() and any(destination.iterdir())):
        raise ValueError('Каталог распаковки должен быть пустым и не являться symlink')
    with tarfile.open(archive, 'r:gz') as bundle:
        members = bundle.getmembers()
        if len(members) > 5000 or sum(m.size for m in members) > 256 * 1024 * 1024:
            raise ValueError('Превышен допустимый размер пакета')
        names = [m.name for m in members]
        if len(names) != len(set(names)):
            raise ValueError('Дублирующиеся пути в пакете')
        for member in members:
            safe_name(member.name)
            if not member.isfile():
                raise ValueError('В пакете разрешены только обычные файлы')
        manifest_member = bundle.getmember(MANIFEST)
        if manifest_member.size > 2 * 1024 * 1024:
            raise ValueError('Некорректный manifest')
        manifest_bytes = bundle.extractfile(manifest_member).read()
        manifest = json.loads(manifest_bytes)
        entries = manifest['files']
        expected = {item['path']: item for item in entries}
        if manifest.get('format') != 1 or len(expected) != len(entries) or set(names) != set(expected) | {MANIFEST}:
            raise ValueError('Состав архива не совпадает с manifest')
        verified = {}
        for name, entry in expected.items():
            safe_name(name)
            if entry['mode'] not in (0o644, 0o755):
                raise ValueError('Недопустимые права файла')
            data = bundle.extractfile(name).read()
            if hashlib.sha256(data).hexdigest() != entry['sha256']:
                raise ValueError('Хеш файла не совпадает: ' + name)
            verified[name] = data
        fingerprint = hashlib.sha256(json.dumps(entries, sort_keys=True, separators=(',', ':')).encode()).hexdigest()
        if fingerprint != manifest['tree_sha256']:
            raise ValueError('Хеш дерева файлов не совпадает')
        destination.mkdir(parents=True, exist_ok=True)
        for name, data in {**verified, MANIFEST: manifest_bytes}.items():
            target = destination.joinpath(*safe_name(name).parts)
            target.parent.mkdir(parents=True, exist_ok=True)
            target.write_bytes(data)
            os.chmod(target, expected[name]['mode'] if name in expected else 0o644)
    return manifest


if __name__ == '__main__':
    extract(sys.argv[1], sys.argv[2])
PY_EXTRACT_REALITY
if [[ -n "$EXTRACT_ONLY" ]]; then
  echo "Пакет проверен и распакован: $DESTINATION"
else
  "$PYTHON" "$DESTINATION/scripts/bootstrap_install.py" --source "$DESTINATION" "${ARGS[@]}"
fi
exit 0
